// Log/transport fixture, not a compiler. Run with Node as the temporary `compile` entry point.
const fs = require('node:fs');
const path = require('node:path');
const folder = process.argv.at(-1);
const file = path.join(folder, path.basename(folder) + '.ino');
const source = fs.readFileSync(file, 'utf8');
const lines = source.split('\n');
const preview = source.includes('// Generated by EduBoard IDE');
const index = lines.findIndex(line => line.includes(preview ? 'void loop()' : 'BROKEN_CPP'));
if (index < 0) { console.log('fixture compile succeeded'); process.exit(0); }
const column = preview ? 1 : lines[index].indexOf('BROKEN_CPP') + 1;
const message = preview ? 'fixture preview compiler error' : 'fixture undeclared BROKEN_CPP';
const output = Buffer.from('\x1b[31m' + file + ':' + (index + 1) + ':' + column + ': error: ' + message + '\x1b[0m\n'
  + path.join(path.dirname(folder), 'dependency', path.basename(file)) + ':2:1: error: fixture library error\n'
  + file + ':99999:1: note: fixture unmapped line directive\n'
  + 'Error during build: exit status 1\n');
process.stderr.write(output.subarray(0, 17));
setTimeout(() => { process.stderr.write(output.subarray(17)); process.exitCode = 1; }, 40);
